        ("什么是货币政策？", "货币政策是中央银行通过调整利率、准备金率和公开市场操作来控制货币供应量的手段"),
        ("什么是CPI？", "消费者物价指数（CPI）衡量一篮子消费品和服务价格的变动，是衡量通货膨胀的主要指标"),
