        ("什么是贸易顺差和逆差？", "当一个国家的出口总值大于进口总值时为贸易顺差，反之为贸易逆差"),
        ("什么是人均GDP？", "人均GDP是一个国家的GDP除以其人口总数，是衡量国民生活水平的重要指标"),
