        ("什么是边际效用？", "边际效用是指消费者每增加一单位消费所获得的额外满足感，通常随消费量增加而递减"),
        ("什么是机会成本？", "机会成本是做出某一选择时所放弃的最佳替代选择的价值，是经济学中重要的决策概念"),
        ("什么是外汇储备？", "外汇储备是一国政府持有的外国货币资产，用于稳定汇率和应对国际支付需求"),
        ("什么是股票市场的牛市和熊市？", "牛市指股票价格持续上涨的市场行情，熊市指价格持续下跌。牛市中投资者信心高涨，熊市中则悲观"),
        ("什么是通胀率2%的目标？", "许多央行将2%作为通胀目标，认为适度通胀有利于经济增长，既能鼓励消费又不会过度侵蚀购买力"),
