        ("阿波罗11号任务有什么意义？", "1969年7月20日，美国阿波罗11号任务将人类送上月球，阿姆斯特朗成为第一个踏上月球的人"),
        ("哈勃太空望远镜发射于哪一年？", "1990年发射，位于距地球约547公里的轨道上，为我们提供了大量深空天体的壮丽图像"),
