        ("旅行者1号飞了多远？", "旅行者1号于1977年发射，是离地球最远的人造物体，已飞出日球层进入星际空间，距地球超过240亿公里"),
        ("中国的载人航天从什么时候开始？", "2003年10月15日，杨利伟搭乘'神舟五号'飞船进入太空，中国成为第三个独立掌握载人航天技术的国家"),
        ("什么是地球同步轨道？", "地球同步轨道高度约35786公里，卫星在此轨道上的运行周期与地球自转周期相同，看起来静止在天空中"),
        ("SpaceX有什么创新？", "SpaceX是埃隆·马斯克创办的航天公司，实现了火箭第一级回收复用，大大降低了航天发射成本"),
        ("黑洞的第一张照片是什么时候拍到的？", "2019年4月，事件视界望远镜团队发布了人类首张黑洞照片，拍摄的是M87星系中心的超大质量黑洞"),
        ("嫦娥工程是什么？", "嫦娥工程是中国的月球探测计划，嫦娥四号于2019年首次在月球背面软着陆，嫦娥五号于2020年成功采样返回"),
        ("火星车'好奇号'发现了什么？", "NASA的好奇号火星车于2012年登陆火星，发现了火星曾有适合微生物生存环境的证据"),
        ("韦伯太空望远镜有什么特点？", "詹姆斯·韦伯太空望远镜于2021年发射，是哈勃的继任者，主要观测红外波段，能看到更古老的宇宙"),
