        ("西班牙海鲜饭是什么？", "西班牙海鲜饭（Paella）起源于瓦伦西亚，用藏红花调色，配以海鲜、鸡肉和蔬菜"),
        ("秘鲁菜为什么受到全球关注？", "秘鲁菜融合了原住民、西班牙、非洲、日本和中国的烹饪传统，酸橘汁腌鱼（Ceviche）是国菜"),
        ("摩洛哥的塔吉锅是什么？", "塔吉锅是一种用圆锥形陶锅慢炖的摩洛哥传统菜肴，通常用羊肉或鸡肉配水果、坚果和香料"),
