        ("酱油是怎么制作的？", "酱油以大豆和小麦为原料，经过米曲霉发酵和盐水浸泡，历时数月到数年的酿造过程"),
        ("奶酪有多少种类？", "全世界有超过1800种奶酪，按质地分为软质、半软质、硬质和超硬质，制作过程涉及乳酸菌发酵和凝乳"),
        ("泡菜是怎么发酵的？", "泡菜通过乳酸菌发酵蔬菜制成，盐渍后蔬菜中的乳酸菌将糖分转化为乳酸，产生独特的酸味"),
        ("啤酒的酿造原理是什么？", "啤酒用大麦芽经过糖化、煮沸加啤酒花、然后用酵母菌发酵而成，酵母将糖分转化为酒精和二氧化碳"),
        ("什么是腌制？", "腌制是用盐、糖、醋或烟熏等方法保存食物的技术，通过降低水活度或改变pH值来抑制微生物生长"),
        ("醋是怎么生产的？", "醋的生产分两步：先用酵母菌将糖发酵为酒精，再用醋酸杆菌将酒精氧化为醋酸"),
        ("什么是巴氏杀菌？", "巴氏杀菌是法国微生物学家巴斯德发明的低温灭菌法，将液体加热到60-85°C保持一段时间以杀死有害微生物"),
        ("纳豆是怎么制作的？", "纳豆是将煮熟的大豆用纳豆杆菌发酵而成的日本传统食品，有独特的黏丝和气味，富含维生素K"),
